
INSERT INTO price_price (id, name, model, price, description_ru, description_uz, description_en) VALUES
(1, 'Toyota', 'Levin', 250000000,
 'Это переднеприводный автомобиль C-класса, который с 2014 года выпускается в Китае совместным предприятием Guangzhou-Toyota и представляет собой версию глобальной модели Toyota Corolla с изменённым дизайном экстерьера. Ранее под именем Corolla Levin выпускались спортивные купе в Японии (знаменитые серии AE86, AE101 и др.), но современные версии для китайского рынка выполнены в кузове седан',
 'Bu 2014-yildan beri Xitoyda Guangzhou-Toyota qoʻshma korxonasi tomonidan ishlab chiqarilayotgan old gʻildirak yuritmali C-sinf avtomobili. U global Toyota Corolla modelining tashqi dizayni oʻzgartirilgan versiyasidir. Ilgari Corolla Levin nomi ostida Yaponiyada sport kupelari (mashhur AE86, AE101 va boshqa seriyalar) ishlab chiqarilgan, ammo Xitoy bozori uchun zamonaviy versiyalar sedan kuzovida tayyorlanadi.',
 'A front-wheel-drive C-segment car produced in China since 2014 by the Guangzhou-Toyota joint venture. It is a version of the global Toyota Corolla with a redesigned exterior. In the past, the Corolla Levin name was used for sporty coupes in Japan (the famous AE86, AE101 and other series), but the modern versions for the Chinese market are sedans.'),
(2, 'Chevrolet', 'Cobalt', 165000000,
 'Бюджетный седан B-класса, разработанный бразильским подразделением GM. С 2013 года выпускается в Узбекистане на заводе в Асаке (ныне UzAuto Motors). Отличается просторным салоном и большим багажником объёмом 545 литров. Оснащается бензиновым двигателем 1.5 л мощностью около 106 л.с. с механической или 6-ступенчатой автоматической коробкой передач. Один из самых популярных автомобилей в Средней Азии.',
 'GM kompaniyasining Braziliya boʻlimi tomonidan ishlab chiqilgan arzon B-sinf sedani. 2013-yildan beri Oʻzbekistonda Asaka zavodida (hozirgi UzAuto Motors) ishlab chiqariladi. Keng salon va 545 litrli katta yukxonasi bilan ajralib turadi. Taxminan 106 ot kuchiga ega 1.5 litrli benzin dvigateli hamda mexanik yoki 6 pogʻonali avtomatik uzatmalar qutisi bilan jihozlanadi. Oʻrta Osiyodagi eng ommabop avtomobillardan biri.',
 'A budget B-segment sedan developed by GM''s Brazilian division. Since 2013 it has been produced in Uzbekistan at the Asaka plant (now UzAuto Motors). It stands out for its roomy interior and large 545-litre boot. It is powered by a 1.5 L petrol engine of about 106 hp with a manual or 6-speed automatic gearbox. One of the most popular cars in Central Asia.'),
(3, 'Chevrolet', 'Gentra', 185000000,
 'Седан C-класса, преемник известной модели Lacetti. Производится UzAuto Motors с 2013 года. Двигатель 1.5 л мощностью 107 л.с. работает в паре с механической или 6-ступенчатой автоматической коробкой. Ценится за надёжность, мягкую подвеску, недорогое обслуживание и доступность запчастей.',
 'Mashhur Lacetti modelining vorisi boʻlgan C-sinf sedani. 2013-yildan beri UzAuto Motors tomonidan ishlab chiqariladi. 107 ot kuchiga ega 1.5 litrli dvigatel mexanik yoki 6 pogʻonali avtomatik uzatmalar qutisi bilan ishlaydi. Ishonchliligi, yumshoq osmasi, arzon xizmat koʻrsatilishi va ehtiyot qismlarning oson topilishi uchun qadrlanadi.',
 'A C-segment sedan and successor to the well-known Lacetti. Produced by UzAuto Motors since 2013. Its 1.5 L, 107 hp engine is paired with a manual or 6-speed automatic gearbox. Valued for its reliability, soft suspension, low maintenance costs and easy availability of spare parts.'),
(4, 'Chevrolet', 'Tracker', 260000000,
 'Компактный городской кроссовер второго поколения, представленный в 2019 году. Оснащается трёхцилиндровым турбодвигателем 1.2 л мощностью около 130 л.с. и 6-ступенчатым автоматом, привод передний. Экономичный расход топлива, высокий дорожный просвет и современная мультимедийная система делают его удобным для города.',
 '2019-yilda taqdim etilgan ikkinchi avlod ixcham shahar krossoveri. Taxminan 130 ot kuchiga ega 1.2 litrli uch silindrli turbodvigatel va 6 pogʻonali avtomat bilan jihozlangan, yuritmasi old gʻildiraklarda. Tejamkor yoqilgʻi sarfi, baland klirens va zamonaviy multimedia tizimi uni shahar uchun qulay qiladi.',
 'A second-generation compact urban crossover introduced in 2019. It is fitted with a 1.2 L three-cylinder turbo engine of about 130 hp and a 6-speed automatic, with front-wheel drive. Low fuel consumption, high ground clearance and a modern infotainment system make it well suited to city driving.'),
(5, 'Chevrolet', 'Malibu', 380000000,
 'Седан D-класса девятого поколения, выпускается с 2015 года. Имеет вытянутый элегантный кузов, просторный задний ряд и богатое оснащение. Предлагается с турбированными бензиновыми двигателями 1.5 л и 2.0 л. Популярен в Средней Азии как статусный и комфортный семейный автомобиль.',
 '2015-yildan beri ishlab chiqarilayotgan toʻqqizinchi avlod D-sinf sedani. Uzun va nafis kuzov, keng orqa oʻrindiqlar va boy jihozlarga ega. 1.5 va 2.0 litrli turboli benzin dvigatellari bilan taklif etiladi. Oʻrta Osiyoda nufuzli va qulay oilaviy avtomobil sifatida mashhur.',
 'A ninth-generation D-segment sedan produced since 2015. It has a long, elegant body, a spacious rear seat and rich equipment. It is offered with 1.5 L and 2.0 L turbocharged petrol engines. Popular in Central Asia as a prestigious and comfortable family car.'),
(6, 'Toyota', 'Camry', 520000000,
 'Один из самых продаваемых седанов бизнес-класса в мире. Девятое поколение (XV80) представлено в 2023 году. В зависимости от рынка доступны бензиновые двигатели 2.0 и 2.5 л, а также гибридная установка на базе мотора 2.5 л. Комфортный просторный салон, высокая надёжность и хорошая сохранность стоимости на вторичном рынке.',
 'Dunyodagi eng koʻp sotiladigan biznes-klass sedanlaridan biri. Toʻqqizinchi avlod (XV80) 2023-yilda taqdim etilgan. Bozorga qarab 2.0 va 2.5 litrli benzin dvigatellari, shuningdek 2.5 litrli motor asosidagi gibrid qurilma mavjud. Qulay va keng salon, yuqori ishonchlilik hamda ikkilamchi bozorda narxini yaxshi saqlashi bilan ajralib turadi.',
 'One of the best-selling business-class sedans in the world. The ninth generation (XV80) was introduced in 2023. Depending on the market, 2.0 L and 2.5 L petrol engines are available, as well as a hybrid powertrain based on the 2.5 L engine. A comfortable, roomy interior, high reliability and strong resale value.'),
(7, 'Toyota', 'Land Cruiser 300', 1500000000,
 'Полноразмерный рамный внедорожник, представленный в 2021 году на новой платформе TNGA-F. Оснащается бензиновым битурбо V6 3.5 л (415 л.с.) или дизельным битурбо V6 3.3 л (309 л.с.), 10-ступенчатым автоматом и постоянным полным приводом. Легендарная проходимость, надёжность и роскошный салон.',
 '2021-yilda yangi TNGA-F platformasida taqdim etilgan ramali toʻliq oʻlchamli yoʻltanlamas. 3.5 litrli benzinli biturbo V6 (415 ot kuchi) yoki 3.3 litrli dizel biturbo V6 (309 ot kuchi), 10 pogʻonali avtomat va doimiy toʻliq yuritma bilan jihozlanadi. Afsonaviy yoʻltanlamasligi, ishonchliligi va hashamatli saloni bilan mashhur.',
 'A full-size body-on-frame SUV introduced in 2021 on the new TNGA-F platform. It is powered by a 3.5 L twin-turbo V6 petrol engine (415 hp) or a 3.3 L twin-turbo V6 diesel (309 hp), with a 10-speed automatic and permanent four-wheel drive. Legendary off-road ability, reliability and a luxurious interior.'),
(8, 'Hyundai', 'Sonata', 420000000,
 'Седан D-класса восьмого поколения (DN8), выпускается с 2019 года, в 2023 году получил обновлённый дизайн. Предлагается с бензиновыми двигателями 2.0 л (150 л.с.) и 2.5 л (180 л.с.) и автоматической коробкой передач. Выделяется спортивным силуэтом, тихим салоном и большим количеством систем помощи водителю.',
 '2019-yildan beri ishlab chiqarilayotgan sakkizinchi avlod (DN8) D-sinf sedani, 2023-yilda dizayni yangilangan. 2.0 litrli (150 ot kuchi) va 2.5 litrli (180 ot kuchi) benzin dvigatellari hamda avtomatik uzatmalar qutisi bilan taklif etiladi. Sport uslubidagi siluet, sokin salon va haydovchiga yordam beruvchi koʻplab tizimlar bilan ajralib turadi.',
 'An eighth-generation (DN8) D-segment sedan produced since 2019, with a refreshed design in 2023. It is offered with 2.0 L (150 hp) and 2.5 L (180 hp) petrol engines and an automatic gearbox. It stands out for its sporty silhouette, quiet cabin and wide range of driver assistance systems.'),
(9, 'Hyundai', 'Tucson', 400000000,
 'Компактный кроссовер четвёртого поколения (NX4), выпускается с 2020 года. Узнаваем по ходовым огням, спрятанным в решётке радиатора. Бензиновые двигатели 2.0 л (150 л.с.) и 2.5 л (190 л.с.), передний или полный привод. Просторный салон, цифровая приборная панель и богатое оснащение.',
 '2020-yildan beri ishlab chiqarilayotgan toʻrtinchi avlod (NX4) ixcham krossover. Radiator panjarasiga yashirilgan kunduzgi chiroqlari bilan tanilgan. 2.0 litrli (150 ot kuchi) va 2.5 litrli (190 ot kuchi) benzin dvigatellari, old yoki toʻliq yuritma. Keng salon, raqamli asboblar paneli va boy jihozlar.',
 'A fourth-generation (NX4) compact crossover produced since 2020. It is recognisable by the daytime running lights hidden in the radiator grille. Petrol engines of 2.0 L (150 hp) and 2.5 L (190 hp), front- or all-wheel drive. A roomy interior, digital instrument cluster and rich equipment.'),
(10, 'Kia', 'K5', 390000000,
 'Седан D-класса, пришедший на смену модели Optima в 2019 году. Имеет динамичный силуэт в стиле фастбэк и фирменные ходовые огни в форме «кардиограммы». Двигатели 2.0 л (150 л.с.) и 2.5 л (194 л.с.) с автоматической коробкой передач. Сочетает спортивный дизайн, комфорт и современные технологии.',
 '2019-yilda Optima modelining oʻrnini egallagan D-sinf sedani. Fastbek uslubidagi dinamik siluet va «kardiogramma» shaklidagi oʻziga xos kunduzgi chiroqlarga ega. Avtomatik uzatmalar qutisi bilan 2.0 litrli (150 ot kuchi) va 2.5 litrli (194 ot kuchi) dvigatellar. Sport dizayni, qulaylik va zamonaviy texnologiyalarni oʻzida mujassam etgan.',
 'A D-segment sedan that replaced the Optima in 2019. It has a dynamic fastback-style silhouette and signature “heartbeat” daytime running lights. Engines of 2.0 L (150 hp) and 2.5 L (194 hp) with an automatic gearbox. It combines sporty design, comfort and modern technology.'),
(11, 'Kia', 'Sportage', 370000000,
 'Компактный кроссовер пятого поколения (NQ5), выпускается с 2021 года. В салоне установлен изогнутый панорамный дисплей, объединяющий приборную панель и мультимедиа. Бензиновые двигатели 2.0 и 2.5 л, передний или полный привод. Один из самых популярных кроссоверов своего класса.',
 '2021-yildan beri ishlab chiqarilayotgan beshinchi avlod (NQ5) ixcham krossover. Salonda asboblar paneli va multimediani birlashtirgan egilgan panorama displeyi oʻrnatilgan. 2.0 va 2.5 litrli benzin dvigatellari, old yoki toʻliq yuritma. Oʻz sinfidagi eng ommabop krossoverlardan biri.',
 'A fifth-generation (NQ5) compact crossover produced since 2021. The cabin features a curved panoramic display that combines the instrument cluster and infotainment screen. 2.0 L and 2.5 L petrol engines, front- or all-wheel drive. One of the most popular crossovers in its class.'),
(12, 'BYD', 'Song Plus', 400000000,
 'Среднеразмерный кроссовер китайской компании BYD. Выпускается в версии подключаемого гибрида DM-i (бензиновый мотор 1.5 л и электродвигатель) и в полностью электрической версии EV. Использует фирменную батарею Blade. Гибрид способен проехать на электричестве более 100 км, а общий запас хода превышает 1000 км.',
 'Xitoyning BYD kompaniyasiga tegishli oʻrta oʻlchamli krossover. DM-i plagin-gibrid (1.5 litrli benzin motori va elektr dvigatel) hamda toʻliq elektr EV versiyalarida ishlab chiqariladi. Kompaniyaning oʻziga xos Blade batareyasidan foydalanadi. Gibrid versiya faqat elektrda 100 km dan ortiq yura oladi, umumiy yurish masofasi esa 1000 km dan oshadi.',
 'A mid-size crossover from the Chinese company BYD. It is available as a DM-i plug-in hybrid (a 1.5 L petrol engine plus an electric motor) and as a fully electric EV. It uses the company''s own Blade battery. The hybrid can travel more than 100 km on electricity alone, and its total range exceeds 1000 km.'),
(13, 'BYD', 'Han', 480000000,
 'Флагманский седан бизнес-класса BYD в фирменном стиле «Dragon Face». Доступен как полностью электрический (EV) и как подключаемый гибрид (DM). Полноприводная электрическая версия разгоняется до 100 км/ч примерно за 3,9 секунды. Просторный салон, натуральная кожа, большой поворотный экран мультимедиа.',
 'BYD kompaniyasining «Dragon Face» uslubidagi flagman biznes-klass sedani. Toʻliq elektr (EV) va plagin-gibrid (DM) versiyalarida mavjud. Toʻliq yuritmali elektr versiyasi soatiga 100 km tezlikka taxminan 3,9 soniyada chiqadi. Keng salon, tabiiy charm va katta aylanuvchi multimedia ekrani.',
 'BYD''s flagship business-class sedan in the brand''s signature “Dragon Face” style. It is available as a fully electric (EV) model and as a plug-in hybrid (DM). The all-wheel-drive electric version accelerates to 100 km/h in about 3.9 seconds. A spacious interior, genuine leather and a large rotating infotainment screen.'),
(14, 'Haval', 'Jolion', 260000000,
 'Компактный кроссовер марки Haval (Great Wall Motors), выпускается с 2020 года. Оснащается турбодвигателем 1.5 л мощностью около 143–150 л.с. и 7-ступенчатой роботизированной коробкой с двумя сцеплениями, привод передний или полный. Хорошее оснащение за свои деньги, просторный задний ряд.',
 '2020-yildan beri ishlab chiqarilayotgan Haval (Great Wall Motors) markasining ixcham krossoveri. Taxminan 143–150 ot kuchiga ega 1.5 litrli turbodvigatel va ikki ilashishli 7 pogʻonali robotlashtirilgan uzatmalar qutisi bilan jihozlanadi, yuritmasi old yoki toʻliq. Narxiga nisbatan yaxshi jihozlangan, orqa oʻrindiqlari keng.',
 'A compact crossover from Haval (Great Wall Motors) produced since 2020. It is fitted with a 1.5 L turbo engine of about 143–150 hp and a 7-speed dual-clutch gearbox, with front- or all-wheel drive. Good equipment for the money and a roomy rear seat.'),
(15, 'Chery', 'Tiggo 7 Pro', 300000000,
 'Компактный кроссовер китайской марки Chery, выпускается с 2020 года. Турбированный двигатель 1.5 л мощностью 147 л.с. работает в паре с вариатором. Богатая комплектация уже в базе: камеры кругового обзора, большой сенсорный экран, климат-контроль и цифровая приборная панель.',
 '2020-yildan beri ishlab chiqarilayotgan Xitoyning Chery markasiga tegishli ixcham krossover. 147 ot kuchiga ega 1.5 litrli turboli dvigatel variator bilan ishlaydi. Bazaviy komplektatsiyadayoq boy jihozlangan: aylanma koʻrinish kameralari, katta sensorli ekran, klimat-nazorat va raqamli asboblar paneli.',
 'A compact crossover from the Chinese brand Chery, produced since 2020. Its 1.5 L turbocharged engine with 147 hp is paired with a CVT. Rich equipment even in the base version: surround-view cameras, a large touchscreen, climate control and a digital instrument cluster.'),
(16, 'Mercedes-Benz', 'E-Class', 950000000,
 'Седан бизнес-класса шестого поколения (W214), представленный в 2023 году. Опционально оснащается панелью MBUX Superscreen с отдельным экраном для пассажира. Двигатели с системами мягкого гибрида, а также подключаемые гибридные версии. Эталон комфорта, безопасности и технологий в своём классе.',
 '2023-yilda taqdim etilgan oltinchi avlod (W214) biznes-klass sedani. Qoʻshimcha ravishda yoʻlovchi uchun alohida ekranga ega MBUX Superscreen paneli bilan jihozlanishi mumkin. Yumshoq gibrid tizimli dvigatellar, shuningdek plagin-gibrid versiyalar taklif etiladi. Oʻz sinfida qulaylik, xavfsizlik va texnologiyalar namunasi.',
 'A sixth-generation (W214) business-class sedan introduced in 2023. It can be optionally fitted with the MBUX Superscreen, which includes a separate screen for the passenger. Mild-hybrid engines are offered, as well as plug-in hybrid versions. A benchmark for comfort, safety and technology in its class.'),
(17, 'BMW', '5 Series', 900000000,
 'Седан бизнес-класса восьмого поколения (G60), представленный в 2023 году. Впервые в истории модели доступна полностью электрическая версия i5. Также предлагаются бензиновые, дизельные и гибридные двигатели. Классическая для BMW управляемость, задний или полный привод xDrive, изогнутый дисплей в салоне.',
 '2023-yilda taqdim etilgan sakkizinchi avlod (G60) biznes-klass sedani. Model tarixida ilk bor toʻliq elektr i5 versiyasi mavjud. Shuningdek benzin, dizel va gibrid dvigatellar taklif etiladi. BMW uchun klassik boshqaruvchanlik, orqa yoki xDrive toʻliq yuritma, salonda egilgan displey.',
 'An eighth-generation (G60) business-class sedan introduced in 2023. For the first time in the model''s history, a fully electric i5 version is available. Petrol, diesel and hybrid engines are also offered. Classic BMW handling, rear-wheel or xDrive all-wheel drive, and a curved display in the cabin.'),
(18, 'Lexus', 'LX 600', 1900000000,
 'Флагманский внедорожник Lexus четвёртого поколения, выпускается с 2021 года на платформе TNGA-F, общей с Toyota Land Cruiser 300. Бензиновый битурбо V6 3.5 л мощностью 409 л.с., 10-ступенчатый автомат и постоянный полный привод. Роскошный салон, адаптивная подвеска и высокая проходимость.',
 'Lexus markasining toʻrtinchi avlod flagman yoʻltanlamasi, 2021-yildan beri Toyota Land Cruiser 300 bilan umumiy TNGA-F platformasida ishlab chiqariladi. 409 ot kuchiga ega 3.5 litrli benzinli biturbo V6, 10 pogʻonali avtomat va doimiy toʻliq yuritma. Hashamatli salon, adaptiv osma va yuqori yoʻltanlamaslik.',
 'Lexus''s fourth-generation flagship SUV, produced since 2021 on the TNGA-F platform shared with the Toyota Land Cruiser 300. A 3.5 L twin-turbo V6 petrol engine with 409 hp, a 10-speed automatic and permanent four-wheel drive. A luxurious interior, adaptive suspension and strong off-road ability.'),
(19, 'Tesla', 'Model 3', 520000000,
 'Электрический седан американской компании Tesla. Обновлённая версия (Highland) представлена в 2023 году. Запас хода в зависимости от версии — до 600 км и более по циклу WLTP. Минималистичный салон с центральным экраном 15,4 дюйма, обновления по воздуху и система помощи водителю Autopilot.',
 'Amerikaning Tesla kompaniyasiga tegishli elektr sedan. Yangilangan versiyasi (Highland) 2023-yilda taqdim etilgan. Versiyaga qarab WLTP sikli boʻyicha yurish masofasi 600 km va undan ortiq. Markazida 15,4 dyuymli ekranga ega minimalistik salon, internet orqali yangilanishlar va Autopilot haydovchiga yordam tizimi.',
 'An electric sedan from the American company Tesla. The updated version (Highland) was introduced in 2023. Depending on the version, the range is up to 600 km or more on the WLTP cycle. A minimalist interior with a 15.4-inch central screen, over-the-air updates and the Autopilot driver assistance system.'),
(20, 'Zeekr', '001', 600000000,
 'Электрический лифтбек премиальной марки Zeekr, принадлежащей Geely, выпускается с 2021 года. Построен на архитектуре SEA. Полноприводная версия с двумя электромоторами развивает около 544 л.с. и разгоняется до 100 км/ч менее чем за 4 секунды. Запас хода более 700 км по циклу CLTC, пневмоподвеска и просторный салон.',
 'Geely kompaniyasiga tegishli premium Zeekr markasining elektr liftbegi, 2021-yildan beri ishlab chiqariladi. SEA arxitekturasi asosida qurilgan. Ikkita elektr motorli toʻliq yuritmali versiyasi taxminan 544 ot kuchiga ega va soatiga 100 km tezlikka 4 soniyadan kamroq vaqtda chiqadi. CLTC sikli boʻyicha 700 km dan ortiq yurish masofasi, pnevmatik osma va keng salon.',
 'An electric liftback from Zeekr, a premium brand owned by Geely, produced since 2021. It is built on the SEA architecture. The all-wheel-drive version with two electric motors produces about 544 hp and accelerates to 100 km/h in under 4 seconds. A range of more than 700 km on the CLTC cycle, air suspension and a spacious interior.')
ON CONFLICT (id) DO NOTHING;


SELECT setval(pg_get_serial_sequence('price_price', 'id'), (SELECT MAX(id) FROM price_price));
